#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

int main() {
    string s;
    cin >> s;

    unordered_map<int, long long> count;
    count[0] = 1;
    int balance = 0;
    long long total = 0;
    for (char ch : s) {
        bool vowel = ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
        balance += vowel ? 1 : -1;
        total += count[balance];
        count[balance]++;
    }
    cout << total << "\n";

    return 0;
}

